// One-time correction: old permission UI had the labels for collection and cash daily reversed.
// Swap the stored keys once so each employee's saved choices follow the corrected labels.
try {
  db.exec('CREATE TABLE IF NOT EXISTS permission_migrations (migration_key TEXT PRIMARY KEY, applied_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP)');
  const migrationKey='swap_cashbox_finance_permission_keys_v1';
  if (!db.prepare('SELECT 1 FROM permission_migrations WHERE migration_key=?').get(migrationKey)) {
    const users=db.prepare('SELECT id,permissions FROM users').all();
    const update=db.prepare('UPDATE users SET permissions=? WHERE id=?');
    const tx=db.transaction(()=>{
      for (const u of users) {
        let perms=[]; try { perms=JSON.parse(u.permissions||'[]'); } catch { perms=[]; }
        const mapped=perms.map(k=>k==='cashbox'?'finance':k==='finance'?'cashbox':k==='edit_cashbox'?'edit_finance':k==='edit_finance'?'edit_cashbox':k);
        update.run(JSON.stringify([...new Set(mapped)]),u.id);
      }
      db.prepare('INSERT INTO permission_migrations(migration_key) VALUES(?)').run(migrationKey);
    });
    tx();
  }
} catch(e) { console.error('Cashbox/collection permission key migration failed:',e.message); }
