const secret=process.env.JWT_SECRET||'local-dev-secret-change-before-production';
function auth(req,res,next){const token=req.cookies.nasim_token;if(!token)return res.status(401).json({error:'يلزم تسجيل الدخول'});try{req.user=jwt.verify(token,secret);const u=db.prepare('SELECT id,username,full_name,role,permissions,active FROM users WHERE id=?').get(req.user.id);if(!u||!u.active)return res.status(401).json({error:'الحساب غير فعال'});u.permissions=JSON.parse(u.permissions);req.user=u;next();}catch(e){return res.status(401).json({error:'جلسة الدخول انتهت'});}}
function permit(key){return (req,res,next)=>{const write=!['GET','HEAD','OPTIONS'].includes(req.method);const allowed=req.user.role==='admin'||(write?req.user.permissions.includes('edit_'+key):req.user.permissions.includes(key)||req.user.permissions.includes('edit_'+key));if(allowed)return next();res.status(403).json({error:write?'ليس لديك صلاحية تعديل هذا القسم؛ صلاحيتك قراءة فقط':'ليس لديك صلاحية لعرض هذا القسم'});}}
function discountLimit(userId,eventDate){const u=db.prepare('SELECT role,discount_normal,discount_special FROM users WHERE id=?').get(userId);if(!u)return 0;if(u.role==='admin')return 100;const dt=new Date(String(eventDate||'')+'T12:00:00');if(!Number.isFinite(dt.getTime()))return Number(u.discount_normal||0);const weekday=dt.getDay();const holiday=db.prepare('SELECT 1 FROM official_holidays WHERE holiday_date=?').get(String(eventDate));return (weekday===4||weekday===5||weekday===6||holiday)?Number(u.discount_special||0):Number(u.discount_normal||0);}
function financeWrite(req,res,next){const role=String(req.user.role||'').toLowerCase();if(!['cashier','accounts','accountant'].includes(role))return res.status(403).json({error:'تسجيل التحصيل متاح للكاشير والحسابات فقط'});if(!req.user.permissions.includes('edit_finance'))return res.status(403).json({error:'ليس لديك صلاحية تعديل التحصيلات؛ صلاحيتك قراءة فقط'});next();}
app.post('/api/login',(req,res)=>{const {username,password}=req.body||{};const u=db.prepare('SELECT * FROM users WHERE username=? AND active=1').get(String(username||''));if(!u||!bcrypt.compareSync(String(password||''),u.password_hash))return res.status(401).json({error:'اسم المستخدم أو كلمة المرور غير صحيحة'});const token=jwt.sign({id:u.id},secret,{expiresIn:'10h'});res.cookie('nasim_token',token,{httpOnly:true,sameSite:'strict',secure:false,maxAge:10*60*60*1000});db.prepare('INSERT INTO audit_logs(user_id,action,entity) VALUES(?,?,?)').run(u.id,'login','users');res.json({id:u.id,username:u.username,name:u.full_name,role:u.role,permissions:JSON.parse(u.permissions)});});
app.post('/api/logout',(req,res)=>{res.clearCookie('nasim_token');res.json({ok:true});});app.get('/api/me',auth,(req,res)=>res.json({id:req.user.id,username:req.user.username,name:req.user.full_name,role:req.user.role,permissions:req.user.permissions}));
// Accounting read APIs and balanced manual journal posting. Mutations require edit_accounting.
app.get('/api/accounting/summary',auth,permit('accounting'),(req,res)=>{
 const accounts=db.prepare('SELECT id,code,name,account_type,parent_id,active FROM accounting_accounts ORDER BY code').all();
 const totals=db.prepare(`SELECT COUNT(DISTINCT e.id) entries,COALESCE(SUM(l.debit),0) debit,COALESCE(SUM(l.credit),0) credit FROM journal_entries e JOIN journal_lines l ON l.entry_id=e.id WHERE e.status='posted'`).get();
 const cash=db.prepare("SELECT COALESCE(SUM(CASE WHEN entry_type='income' THEN amount ELSE -amount END),0) balance FROM cash_journal").get();
 const payments=db.prepare("SELECT COALESCE(SUM(amount),0) amount FROM payments WHERE payment_type='payment'").get();
 res.json({accounts,totals,cashBalance:cash.balance,recordedPayments:payments.amount});
});
app.get('/api/accounting/journals',auth,permit('accounting'),(req,res)=>{
 const from=String(req.query.from||'');const to=String(req.query.to||'');
 if((from&&!/^\d{4}-\d{2}-\d{2}$/.test(from))||(to&&!/^\d{4}-\d{2}-\d{2}$/.test(to))||(from&&to&&from>to))return res.status(400).json({error:'نطاق التاريخ غير صحيح'});
 const rows=db.prepare(`SELECT e.id,e.entry_no,e.entry_date,e.description,e.source_type,e.status,e.created_at,u.full_name created_by_name,COALESCE(SUM(l.debit),0) debit,COALESCE(SUM(l.credit),0) credit FROM journal_entries e LEFT JOIN journal_lines l ON l.entry_id=e.id LEFT JOIN users u ON u.id=e.created_by WHERE (?='' OR e.entry_date>=?) AND (?='' OR e.entry_date<=?) GROUP BY e.id ORDER BY e.entry_date DESC,e.id DESC LIMIT 500`).all(from,from,to,to);res.json(rows);
});
app.get('/api/accounting/trial-balance',auth,permit('accounting'),(req,res)=>{
 const from=String(req.query.from||'0001-01-01'),to=String(req.query.to||'9999-12-31');
 if(!/^\d{4}-\d{2}-\d{2}$/.test(from)||!/^\d{4}-\d{2}-\d{2}$/.test(to)||from>to)return res.status(400).json({error:'حدد فترة صحيحة'});
 const rows=db.prepare(`SELECT a.id,a.code,a.name,a.account_type,
 COALESCE(SUM(CASE WHEN e.status='posted' AND e.entry_date<? THEN l.debit ELSE 0 END),0) opening_debit,
 COALESCE(SUM(CASE WHEN e.status='posted' AND e.entry_date<? THEN l.credit ELSE 0 END),0) opening_credit,
 COALESCE(SUM(CASE WHEN e.status='posted' AND e.entry_date BETWEEN ? AND ? THEN l.debit ELSE 0 END),0) debit,
 COALESCE(SUM(CASE WHEN e.status='posted' AND e.entry_date BETWEEN ? AND ? THEN l.credit ELSE 0 END),0) credit
 FROM accounting_accounts a LEFT JOIN journal_lines l ON l.account_id=a.id LEFT JOIN journal_entries e ON e.id=l.entry_id
 WHERE a.active=1 GROUP BY a.id ORDER BY a.code`).all(from,from,from,to,from,to);
 res.json(rows.map(r=>{const net=Number(r.opening_debit)-Number(r.opening_credit)+Number(r.debit)-Number(r.credit);return {...r,closing_debit:Math.max(net,0),closing_credit:Math.max(-net,0),closing_balance:net}}));
});
app.get('/api/accounting/income-statement',auth,permit('accounting'),(req,res)=>{
 const from=String(req.query.from||'0001-01-01'),to=String(req.query.to||'9999-12-31');
 if(!/^\d{4}-\d{2}-\d{2}$/.test(from)||!/^\d{4}-\d{2}-\d{2}$/.test(to)||from>to)return res.status(400).json({error:'حدد فترة صحيحة'});
 const rows=db.prepare(`SELECT a.id,a.code,a.name,a.account_type,COALESCE(SUM(l.debit),0) debit,COALESCE(SUM(l.credit),0) credit FROM accounting_accounts a LEFT JOIN journal_lines l ON l.account_id=a.id LEFT JOIN journal_entries e ON e.id=l.entry_id AND e.status='posted' AND e.entry_date BETWEEN ? AND ? WHERE a.active=1 AND a.account_type IN ('revenue','expense') AND (l.id IS NULL OR e.id IS NOT NULL) GROUP BY a.id ORDER BY a.code`).all(from,to).map(r=>({...r,amount:r.account_type==='revenue'?Number(r.credit)-Number(r.debit):Number(r.debit)-Number(r.credit)}));
 const revenue=rows.filter(r=>r.account_type==='revenue').reduce((s,r)=>s+r.amount,0),expenses=rows.filter(r=>r.account_type==='expense').reduce((s,r)=>s+r.amount,0);res.json({from,to,rows,revenue,expenses,net_profit:revenue-expenses});
});
app.get('/api/accounting/ledger',auth,permit('accounting'),(req,res)=>{
 const from=String(req.query.from||'0001-01-01'),to=String(req.query.to||'9999-12-31'),accountId=Number(req.query.account_id)||0;
 if(!/^\d{4}-\d{2}-\d{2}$/.test(from)||!/^\d{4}-\d{2}-\d{2}$/.test(to)||from>to)return res.status(400).json({error:'حدد فترة صحيحة'});
 const rows=db.prepare(`SELECT e.entry_no,e.entry_date,e.description entry_description,l.description line_description,a.code,a.name account_name,l.debit,l.credit FROM journal_lines l JOIN journal_entries e ON e.id=l.entry_id JOIN accounting_accounts a ON a.id=l.account_id WHERE e.status='posted' AND e.entry_date BETWEEN ? AND ? AND (?=0 OR a.id=?) ORDER BY e.entry_date,e.id,l.id`).all(from,to,accountId,accountId);res.json(rows);
});
app.post('/api/accounting/journals',auth,permit('accounting'),(req,res)=>{
 const d=req.body||{},date=String(d.entry_date||''),description=String(d.description||'').trim(),lines=Array.isArray(d.lines)?d.lines:[];
 if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||!description||description.length>500)return res.status(400).json({error:'أدخل تاريخ القيد والبيان'});
 const period=db.prepare("SELECT id FROM accounting_periods WHERE status='closed' AND start_date<=? AND end_date>=?").get(date,date);if(period)return res.status(400).json({error:'الفترة المحاسبية مقفلة ولا يمكن تسجيل قيد داخلها'});
 if(lines.length<2||lines.length>100)return res.status(400).json({error:'القيد يجب أن يحتوي على سطرين على الأقل'});
 const clean=[];let debit=0,credit=0;for(const line of lines){const accountId=Number(line.account_id),dr=Number(line.debit||0),cr=Number(line.credit||0);if(!Number.isInteger(accountId)||!Number.isFinite(dr)||!Number.isFinite(cr)||dr<0||cr<0||((dr>0)===(cr>0)))return res.status(400).json({error:'راجع الحساب والمدين والدائن بكل سطر'});if(!db.prepare('SELECT id FROM accounting_accounts WHERE id=? AND active=1').get(accountId))return res.status(400).json({error:'يوجد حساب غير موجود أو غير فعال'});debit+=dr;credit+=cr;clean.push({accountId,dr,cr,description:String(line.description||'').slice(0,250)})}
 if(Math.abs(debit-credit)>0.009)return res.status(400).json({error:'القيد غير متوازن: إجمالي المدين يجب أن يساوي إجمالي الدائن'});
 const tx=db.transaction(()=>{const n=db.prepare('SELECT COALESCE(MAX(id),0)+1 n FROM journal_entries').get().n;const no='JE-'+String(n).padStart(8,'0');const info=db.prepare("INSERT INTO journal_entries(entry_no,entry_date,description,source_type,created_by) VALUES(?,?,?,'manual',?)").run(no,date,description,req.user.id);const put=db.prepare('INSERT INTO journal_lines(entry_id,account_id,description,debit,credit) VALUES(?,?,?,?,?)');for(const l of clean)put.run(info.lastInsertRowid,l.accountId,l.description,debit?l.dr:l.dr,l.cr);db.prepare('INSERT INTO audit_logs(user_id,action,entity,entity_id) VALUES(?,?,?,?)').run(req.user.id,'accounting_journal_created','journal_entries',info.lastInsertRowid);return {id:info.lastInsertRowid,entry_no:no}});try{res.json({ok:true,...tx()})}catch(e){res.status(400).json({error:'تعذر حفظ القيد المحاسبي'})}
});

// Central write gate: all mutating API calls require an explicit edit_<module> grant.
// Existing dedicated safety checks (e.g. cash collection, deletion, approval) still run afterward.
app.use((req,res,next)=>{if(!req.path.startsWith('/api/')||['GET','HEAD','OPTIONS'].includes(req.method)||['/api/login','/api/logout','/api/change-own-password'].includes(req.path))return next();auth(req,res,()=>{if(req.user.role==='admin')return next();const p=req.path;let key=null;
if(/^\/api\/independent-events/.test(p))key='bookings';
if(/^\/api\/(bookings|booking-status|booking-change|booking-change-requests|booking-status-history|booking-rooms|bride-rooms|assign-bride-rooms|booking-work)/.test(p))key='bookings';
else if(/^\/api\/(work-orders|contractor-work|booking-work-contractors)/.test(p))key='work_orders';
else if(/^\/api\/invitations/.test(p))key='invitations';
else if(/^\/api\/(inventory|stock)/.test(p))key='inventory';
else if(/^\/api\/(halls|packages|buffetPackages|buffetItems|addons|operational-addons)/.test(p))key=({halls:'halls',packages:'packages',buffetPackages:'buffet',buffetItems:'buffet',addons:'addons','operational-addons':'operations_addons'})[p.split('/')[2]]||'bookings';
else if(/^\/api\/(users|official-holidays)/.test(p))key='users';
else if(/^\/api\/settings\//.test(p))key='packages';
else if(/^\/api\/backup\//.test(p))key='users';
else if(/^\/api\/(cash-journal\/expense|expense-receipts)/.test(p))key='expenses';
else if(/^\/api\/(payments|collection|cash-journal|contractor-payouts|finance|expense|expenses|receipts)/.test(p))key=p.includes('cash-journal')||p.includes('expense')?'expenses':'finance';
else if(/^\/api\/(offers|offer)/.test(p))key='offers';
else if(/^\/api\/(contractors|contractor-report)/.test(p))key='contractors';
else if(/^\/api\/(followups|inquiries|inquiry)/.test(p))key='followups';
else if(/^\/api\/(discount-requests|additional-discount)/.test(p))key='discounts';
else if(/^\/api\/(reports|saved-reports|data-deletion)/.test(p))key='reports';
if(key&&req.user.permissions.includes('edit_'+key))return next();return res.status(403).json({error:key?'ليس لديك صلاحية تعديل هذا القسم؛ صلاحيتك قراءة فقط':'هذه العملية غير مربوطة بصلاحية تعديل؛ تم منعها لحماية البيانات. راجع مسؤول النظام.'});});});
app.post('/api/change-own-password',auth,(req,res)=>{const {current_password,new_password}=req.body||{};if(!current_password||!new_password||String(new_password).length<10)return res.status(400).json({error:'أدخل كلمة المرور الحالية وكلمة مرور جديدة لا تقل عن 10 أحرف'});const u=db.prepare('SELECT password_hash FROM users WHERE id=?').get(req.user.id);if(!u||!bcrypt.compareSync(String(current_password),u.password_hash))return res.status(400).json({error:'كلمة المرور الحالية غير صحيحة'});db.prepare('UPDATE users SET password_hash=? WHERE id=?').run(bcrypt.hashSync(String(new_password),12),req.user.id);db.prepare('INSERT INTO audit_logs(user_id,action,entity) VALUES(?,?,?)').run(req.user.id,'change_own_password','users');res.json({ok:true})});
app.get('/api/summary',auth,permit('dashboard'),(req,res)=>res.json({halls:db.prepare('SELECT count(*) n FROM halls WHERE active=1').get().n,packages:db.prepare('SELECT count(*) n FROM hall_packages WHERE active=1').get().n,bookings:db.prepare("SELECT count(*) n FROM bookings WHERE status!='cancelled'").get().n,revenue:db.prepare('SELECT coalesce(sum(amount),0) n FROM payments').get().n}));
const catalogs={halls:{table:'halls',perm:'halls',fields:['name','active']},packages:{table:'hall_packages',perm:'packages',fields:['hall_id','name','period','guest_count','price','start_time','end_time','active']},buffetPackages:{table:'buffet_packages',perm:'buffet',fields:['name','price_per_person','active']},buffetItems:{table:'buffet_items',perm:'buffet',fields:['name','active']},addons:{table:'addons',perm:'addons',fields:['name','price_per_person','active']}};
app.get('/api/buffetPackages/:id/items',auth,(req,res)=>{try{const rows=db.prepare('SELECT i.id,i.name,x.quantity FROM buffet_package_items x JOIN buffet_items i ON i.id=x.item_id WHERE x.package_id=? ORDER BY i.name').all(req.params.id);res.json(rows)}catch(e){res.status(400).json({error:e.message})}});
for(const [key,c] of Object.entries(catalogs)){app.get('/api/'+key,auth,(req,res,next)=>{if(req.user.role==='admin'||req.user.permissions.includes(c.perm)||req.user.permissions.includes('bookings'))return next();return res.status(403).json({error:'ليس لديك صلاحية لعرض هذه البيانات'})},(req,res)=>{let rows;if(key==='packages')rows=db.prepare('SELECT p.*,h.name hall_name FROM hall_packages p JOIN halls h ON h.id=p.hall_id ORDER BY h.name,p.period,p.guest_count').all();else if(key==='buffetPackages')rows=db.prepare("SELECT p.*,group_concat(CASE WHEN x.quantity=1 THEN i.name ELSE printf('%s × %d',i.name,CAST(x.quantity AS INTEGER)) END, '، ') items FROM buffet_packages p LEFT JOIN buffet_package_items x ON x.package_id=p.id LEFT JOIN buffet_items i ON i.id=x.item_id GROUP BY p.id ORDER BY p.name").all();else rows=db.prepare(`SELECT * FROM ${c.table} ORDER BY id DESC`).all();res.json(rows)});
app.post('/api/'+key,auth,permit(c.perm),(req,res)=>{try{const data=req.body||{};const vals=c.fields.map(f=>data[f]===undefined?(f==='active'?1:(key==='packages'&&f==='start_time'?'00:00':key==='packages'&&f==='end_time'?'23:59':null)):data[f]);for(const f of c.fields){if(f==='start_time'||f==='end_time'){if(key==='packages')continue}if(f!=='active'&&(data[f]===undefined||data[f]===''))return res.status(400).json({error:'حقل مطلوب: '+f})}const q=`INSERT INTO ${c.table}(${c.fields.join(',')}) VALUES(${c.fields.map(()=>'?').join(',')})`;const info=db.prepare(q).run(...vals);if(key==='buffetPackages'&&(Array.isArray(data.items)||Array.isArray(data.item_ids))){const ins=db.prepare('INSERT OR REPLACE INTO buffet_package_items(package_id,item_id,quantity) VALUES(?,?,?)');for(const item of data.items||[])ins.run(info.lastInsertRowid,Number(item.id),Math.max(1,Math.trunc(Number(item.quantity)||1)));if(!data.items){for(const id of data.item_ids)ins.run(info.lastInsertRowid,id,1)}}db.prepare('INSERT INTO audit_logs(user_id,action,entity,entity_id) VALUES(?,?,?,?)').run(req.user.id,'create',key,info.lastInsertRowid);res.json({id:info.lastInsertRowid,ok:true})}catch(e){res.status(400).json({error:e.message.includes('UNIQUE')?'الاسم موجود بالفعل':e.message})}});
app.put('/api/'+key+'/:id',auth,permit(c.perm),(req,res)=>{try{const data=req.body||{};const fields=c.fields.filter(f=>data[f]!==undefined);if(!fields.length)return res.status(400).json({error:'لا توجد بيانات للتعديل'});const info=db.prepare(`UPDATE ${c.table} SET ${fields.map(f=>f+'=?').join(',')} WHERE id=?`).run(...fields.map(f=>data[f]),req.params.id);if(key==='buffetPackages'&&(Array.isArray(data.items)||Array.isArray(data.item_ids))){const tx=db.transaction(()=>{db.prepare('DELETE FROM buffet_package_items WHERE package_id=?').run(req.params.id);const ins=db.prepare('INSERT OR REPLACE INTO buffet_package_items(package_id,item_id,quantity) VALUES(?,?,?)');for(const item of data.items||[])ins.run(req.params.id,Number(item.id),Math.max(1,Math.trunc(Number(item.quantity)||1)));if(!data.items){for(const id of data.item_ids)ins.run(req.params.id,id,1)}});tx()}res.json({ok:true,changes:info.changes})}catch(e){res.status(400).json({error:e.message})}});
app.delete('/api/'+key+'/:id',auth,(req,res,next)=>{const deletePerm=({halls:'delete_halls',packages:'delete_packages',buffetPackages:'delete_buffet',buffetItems:'delete_buffet',addons:'delete_addons'})[key];if(req.user.role==='admin'||req.user.permissions.includes(deletePerm)||req.user.permissions.includes('delete_all_data'))return next();return res.status(403).json({error:'ليس لديك صلاحية مسح هذا النوع من البيانات'});},(req,res)=>{try{const info=db.prepare(`DELETE FROM ${c.table} WHERE id=?`).run(req.params.id);if(info.changes)db.prepare('INSERT INTO audit_logs(user_id,action,entity,entity_id) VALUES(?,?,?,?)').run(req.user.id,'delete',key,req.params.id);res.json({ok:true,changes:info.changes})}catch(e){res.status(400).json({error:'لا يمكن حذف هذا العنصر لارتباطه ببيانات أخرى؛ عطّله بدلًا من حذفه.'})}})}

