app.get('/api/settings/hall-package-terms',auth,(req,res)=>{if(req.user.role!=='admin'&&!req.user.permissions.includes('packages')&&!req.user.permissions.includes('bookings'))return res.status(403).json({error:'ليس لديك صلاحية'});res.json({terms:db.prepare('SELECT value FROM app_settings WHERE key=?').get('hall_package_terms')?.value||''})});
app.put('/api/settings/hall-package-terms',auth,permit('packages'),(req,res)=>{const terms=String(req.body?.terms||'').trim();db.prepare('INSERT INTO app_settings(key,value) VALUES(?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value').run('hall_package_terms',terms);db.prepare('INSERT INTO audit_logs(user_id,action,entity) VALUES(?,?,?)').run(req.user.id,'update_shared_package_terms','app_settings');res.json({ok:true,terms})});

