app.get('/api/operational-addons',auth,(req,res)=>{if(!req.user.permissions.includes('operations_addons')&&!req.user.permissions.includes('bookings')&&req.user.role!=='admin')return res.status(403).json({error:'ليس لديك صلاحية'});res.json(db.prepare('SELECT * FROM operational_addons ORDER BY name').all())});
app.post('/api/operational-addons',auth,permit('operations_addons'),(req,res)=>{const d=req.body||{};if(!String(d.name||'').trim()||!Number.isFinite(Number(d.price))||Number(d.price)<0)return res.status(400).json({error:'أدخل اسم الإضافة وسعرًا صحيحًا'});try{const x=db.prepare('INSERT INTO operational_addons(name,price,active) VALUES(?,?,?)').run(String(d.name).trim(),Number(d.price),d.active===0?0:1);db.prepare('INSERT INTO audit_logs(user_id,action,entity,entity_id) VALUES(?,?,?,?)').run(req.user.id,'create_operational_addon','operational_addon',x.lastInsertRowid);res.json({ok:true,id:x.lastInsertRowid})}catch(e){res.status(400).json({error:'اسم الإضافة موجود بالفعل أو البيانات غير صحيحة'})}});
app.put('/api/operational-addons/:id',auth,permit('operations_addons'),(req,res)=>{const d=req.body||{};if(!String(d.name||'').trim()||!Number.isFinite(Number(d.price))||Number(d.price)<0)return res.status(400).json({error:'راجع اسم الإضافة والسعر'});try{const x=db.prepare('UPDATE operational_addons SET name=?,price=? WHERE id=?').run(String(d.name).trim(),Number(d.price),req.params.id);db.prepare('INSERT INTO audit_logs(user_id,action,entity,entity_id) VALUES(?,?,?,?)').run(req.user.id,'edit_operational_addon','operational_addon',req.params.id);res.json({ok:true,changes:x.changes})}catch(e){res.status(400).json({error:'تعذر تعديل الإضافة'})}});
app.delete('/api/operational-addons/:id',auth,(req,res,next)=>{if(req.user.role==='admin'||req.user.permissions.includes('delete_operations_addons')||req.user.permissions.includes('delete_all_data'))return next();return res.status(403).json({error:'ليس لديك صلاحية مسح إضافات التشغيل'});},(req,res)=>{try{const x=db.prepare('DELETE FROM operational_addons WHERE id=?').run(req.params.id);if(x.changes)db.prepare('INSERT INTO audit_logs(user_id,action,entity,entity_id) VALUES(?,?,?,?)').run(req.user.id,'delete_operational_addon','operational_addon',req.params.id);res.json({ok:true,changes:x.changes})}catch(e){res.status(400).json({error:'لا يمكن حذف الإضافة لأنها مرتبطة ببيانات أخرى؛ عطّلها بدلًا من ذلك.'})}});
app.get('/api/contractors',auth,permit('contractors'),(req,res)=>res.json(db.prepare('SELECT c.*,h.name hall_name FROM contractors c JOIN halls h ON h.id=c.hall_id ORDER BY h.name,c.job_title,c.full_name').all()));
app.post('/api/contractors',auth,permit('contractors'),(req,res)=>{const d=req.body||{};if(!d.full_name||!d.job_title||!Number(d.hall_id)||!Number.isFinite(Number(d.cost_per_booking))||Number(d.cost_per_booking)<0)return res.status(400).json({error:'أكمل اسم المتعهد والوظيفة والقاعة والتكلفة'});const x=db.prepare('INSERT INTO contractors(full_name,job_title,hall_id,cost_per_booking,active,notes) VALUES(?,?,?,?,?,?)').run(String(d.full_name).trim(),String(d.job_title).trim(),Number(d.hall_id),Number(d.cost_per_booking),d.active===0?0:1,String(d.notes||''));db.prepare('INSERT INTO audit_logs(user_id,action,entity,entity_id) VALUES(?,?,?,?)').run(req.user.id,'create_contractor','contractor',x.lastInsertRowid);res.json({ok:true,id:x.lastInsertRowid})});
app.put('/api/contractors/:id',auth,permit('contractors'),(req,res)=>{const d=req.body||{};if(!String(d.full_name||'').trim()||!String(d.job_title||'').trim()||!Number.isFinite(Number(d.cost_per_booking))||Number(d.cost_per_booking)<0)return res.status(400).json({error:'راجع اسم المتعهد والوظيفة والتكلفة'});try{const x=db.prepare('UPDATE contractors SET full_name=?,job_title=?,cost_per_booking=? WHERE id=?').run(String(d.full_name).trim(),String(d.job_title).trim(),Number(d.cost_per_booking),req.params.id);db.prepare('INSERT INTO audit_logs(user_id,action,entity,entity_id) VALUES(?,?,?,?)').run(req.user.id,'edit_contractor','contractor',req.params.id);res.json({ok:true,changes:x.changes})}catch(e){res.status(400).json({error:'تعذر تعديل بيانات المتعهد'})}});
app.delete('/api/contractors/:id',auth,(req,res,next)=>{if(req.user.role==='admin'||req.user.permissions.includes('delete_contractors')||req.user.permissions.includes('delete_all_data'))return next();return res.status(403).json({error:'ليس لديك صلاحية مسح/تعطيل المتعهدين'});},(req,res)=>{try{const x=db.prepare('UPDATE contractors SET active=0 WHERE id=?').run(req.params.id);if(x.changes)db.prepare('INSERT INTO audit_logs(user_id,action,entity,entity_id) VALUES(?,?,?,?)').run(req.user.id,'deactivate_contractor','contractor',req.params.id);res.json({ok:true,changes:x.changes})}catch(e){res.status(400).json({error:'تعذر تعطيل المتعهد'})}});
app.get('/api/contractor-report',auth,permit('contractor_report'),(req,res)=>{const rows=db.prepare(`SELECT bc.id,bc.booking_id,bc.contractor_id,bc.contractor_name,bc.job_title,bc.hall_name,bc.cost_amount,b.booking_no,b.event_date,b.start_time,b.end_time,b.guest_count,c.full_name customer_name,COALESCE((SELECT SUM(cp.amount) FROM contractor_payouts cp WHERE cp.contractor_id=bc.contractor_id AND (cp.booking_id=bc.booking_id OR cp.booking_id IS NULL)),0) paid_total FROM booking_contractors bc JOIN bookings b ON b.id=bc.booking_id LEFT JOIN customers c ON c.id=b.customer_id ORDER BY b.event_date DESC`).all();res.json({rows,contractors:db.prepare(`SELECT c.id,c.full_name,c.job_title,c.hall_id,COALESCE((SELECT SUM(bc.cost_amount) FROM booking_contractors bc WHERE bc.contractor_id=c.id),0) owed,COALESCE((SELECT SUM(cp.amount) FROM contractor_payouts cp WHERE cp.contractor_id=c.id),0) paid FROM contractors c WHERE c.active=1 ORDER BY c.full_name`).all(),halls:db.prepare('SELECT id,name FROM halls ORDER BY name').all()})});
app.post('/api/contractor-payouts',auth,permit('cashbox'),(req,res)=>{if(req.user.role==='admin')return res.status(403).json({error:'الأدمن لا يسجل صرف الخزنة'});const d=req.body||{},amount=Number(d.amount),contractor=db.prepare('SELECT * FROM contractors WHERE id=? AND active=1').get(Number(d.contractor_id));const bookingId=Number(d.booking_id)||null;if(bookingId&&!db.prepare('SELECT 1 FROM booking_contractors WHERE booking_id=? AND contractor_id=?').get(bookingId,Number(d.contractor_id)))return res.status(400).json({error:'الحجز المختار غير مسند لهذا المتعهد'});if(!contractor||!Number.isFinite(amount)||amount<=0||!['cash','bank_transfer','instapay'].includes(d.method))return res.status(400).json({error:'راجع المتعهد والمبلغ وطريقة الدفع'});const tx=db.transaction(()=>{const next=db.prepare('SELECT COALESCE(MAX(id),0)+1 n FROM cash_journal').get().n;const entry='NS-JV-'+String(next).padStart(8,'0');const j=db.prepare(`INSERT INTO cash_journal(entry_no,entry_type,category,amount,method,description,contractor_id,created_by) VALUES(?,'expense','مستحقات متعهد',?,?,?,?,?)`).run(entry,amount,d.method,`صرف مستحقات ${contractor.full_name} — ${contractor.job_title} — ${String(d.notes||'')}`,contractor.id,req.user.id);const pn=db.prepare('SELECT COALESCE(MAX(id),0)+1 n FROM contractor_payouts').get().n;const receipt='NS-CP-'+String(pn).padStart(8,'0');db.prepare('INSERT INTO contractor_payouts(receipt_no,contractor_id,amount,method,reference,notes,paid_by,journal_id,booking_id) VALUES(?,?,?,?,?,?,?,?,?)').run(receipt,contractor.id,amount,d.method,String(d.reference||''),String(d.notes||''),req.user.id,j.lastInsertRowid,bookingId);db.prepare('INSERT INTO audit_logs(user_id,action,entity,entity_id) VALUES(?,?,?,?)').run(req.user.id,'contractor_payout','contractor',contractor.id);return {receipt_no:receipt,entry_no:entry}});try{res.json(tx())}catch(e){res.status(400).json({error:e.message})}});
app.get('/api/cash-journal',auth,(req,res)=>{const isAdmin=req.user.role==='admin',scope=String(req.query.scope||'all'),canCashbox=isAdmin||req.user.permissions.includes('cashbox')||req.user.permissions.includes('edit_cashbox'),canExpenses=isAdmin||req.user.permissions.includes('expenses')||req.user.permissions.includes('edit_expenses');if(scope==='expenses'&&!canExpenses)return res.status(403).json({error:'ليس لديك صلاحية عرض المصروفات والمشتريات'});if(scope!=='expenses'&&!canCashbox)return res.status(403).json({error:'ليس لديك صلاحية عرض حركة الخزنة واليومية'});const where=scope==='expenses'?"WHERE j.entry_type='expense'":"";const sql=`SELECT j.*,u.full_name employee,c.full_name contractor,b.booking_no,p.payment_type payment_type,p.receipt_no payment_receipt_no,p.notes payment_notes,p.reference payment_reference,e.id receipt_id,e.receipt_no,e.print_count,e.invoice_image FROM cash_journal j LEFT JOIN users u ON u.id=j.created_by LEFT JOIN contractors c ON c.id=j.contractor_id LEFT JOIN bookings b ON b.id=j.booking_id LEFT JOIN payments p ON p.id=j.payment_id LEFT JOIN expense_receipts e ON e.journal_id=j.id ${where} ORDER BY j.id DESC LIMIT 500`;res.json(db.prepare(sql).all())});
app.delete('/api/cash-journal/:id',auth,(req,res,next)=>{if(req.user.role==='admin'||req.user.permissions.includes('delete_cash_journal')||req.user.permissions.includes('delete_all_data'))return next();return res.status(403).json({error:'ليس لديك صلاحية مسح قيود الخزنة'});},(req,res)=>{try{const row=db.prepare('SELECT * FROM cash_journal WHERE id=?').get(req.params.id);if(!row)return res.status(404).json({error:'القيد غير موجود'});if(row.entry_type!=='expense'||row.payment_id||row.contractor_id)return res.status(409).json({error:'لا يمكن مسح هذا القيد مباشرة لأنه مرتبط بتحصيل أو متعهد. يجب تصحيح الحركة من مصدرها للحفاظ على الحسابات.'});const tx=db.transaction(()=>{db.prepare('DELETE FROM expense_receipts WHERE journal_id=?').run(row.id);db.prepare('DELETE FROM cash_journal WHERE id=?').run(row.id);db.prepare('INSERT INTO audit_logs(user_id,action,entity,entity_id,details) VALUES(?,?,?,?,?)').run(req.user.id,'delete','cash_journal',row.id,JSON.stringify({entry_no:row.entry_no,amount:row.amount,category:row.category}));});tx();res.json({ok:true})}catch(e){res.status(400).json({error:'تعذر مسح القيد؛ قد يكون مرتبطًا ببيانات أخرى.'})}});
app.post('/api/cash-journal/expense',auth,(req,res)=>{if(req.user.role==='admin')return res.status(403).json({error:'الأدمن لا يسجل مصروفات الخزنة'});if(!req.user.permissions.includes('edit_expenses'))return res.status(403).json({error:'تسجيل المصروفات يحتاج صلاحية قراءة وتعديل للمصروفات؛ صلاحية الخزنة أو التحصيل وحدها لا تكفي'});const d=req.body||{},amount=Number(d.amount),payee=String(d.payee||'').trim(),image=String(d.invoice_image||'');if(!String(d.category||'').trim()||!String(d.description||'').trim()||!payee||!Number.isFinite(amount)||amount<=0||!['cash','bank_transfer','instapay'].includes(d.method))return res.status(400).json({error:'أكمل بند المصروف والتفاصيل والمبلغ وطريقة الصرف واسم المستفيد'});if(image&&!/^data:image\/(png|jpeg|webp);base64,[A-Za-z0-9+/=]+$/.test(image))return res.status(400).json({error:'صورة الفاتورة يجب أن تكون PNG أو JPG أو WEBP'});if(image&&image.length>6500000)return res.status(400).json({error:'حجم صورة الفاتورة كبير؛ اختر صورة أصغر من 4.5 ميجابايت'});const tx=db.transaction(()=>{const next=db.prepare('SELECT COALESCE(MAX(id),0)+1 n FROM cash_journal').get().n;const entry='NS-JV-'+String(next).padStart(8,'0');const j=db.prepare(`INSERT INTO cash_journal(entry_no,entry_type,category,amount,method,description,payee,created_by) VALUES(?,'expense',?,?,?,?,?,?)`).run(entry,String(d.category).trim(),amount,d.method,String(d.description).trim(),payee,req.user.id);const n=db.prepare('SELECT COALESCE(MAX(id),0)+1 n FROM expense_receipts').get().n;const receipt='NS-EX-'+String(n).padStart(8,'0');db.prepare('INSERT INTO expense_receipts(journal_id,receipt_no,payee,invoice_image) VALUES(?,?,?,?)').run(j.lastInsertRowid,receipt,payee,image||null);db.prepare('INSERT INTO audit_logs(user_id,action,entity,entity_id,details) VALUES(?,?,?,?,?)').run(req.user.id,'cash_expense_receipt','cash_journal',j.lastInsertRowid,JSON.stringify({amount,category:String(d.category).trim(),payee,description:String(d.description).trim(),receipt_no:receipt,entry_no:entry}));return {ok:true,entry_no:entry,receipt_no:receipt,journal_id:j.lastInsertRowid}});try{res.json(tx())}catch(e){res.status(400).json({error:e.message})}});
app.get('/api/expense-receipts/:id',auth,permit('expenses'),(req,res)=>{const r=db.prepare(`SELECT e.*,j.entry_no,j.category,j.amount,j.method,j.description,j.created_at,j.payee,u.full_name employee FROM expense_receipts e JOIN cash_journal j ON j.id=e.journal_id LEFT JOIN users u ON u.id=j.created_by WHERE e.id=? OR e.receipt_no=?`).get(Number(req.params.id)||-1,String(req.params.id));if(!r)return res.status(404).json({error:'الإيصال غير موجود'});res.json(r)});
app.post('/api/expense-receipts/:id/print',auth,permit('expenses'),(req,res)=>{const r=db.prepare('SELECT * FROM expense_receipts WHERE id=? OR receipt_no=?').get(Number(req.params.id)||-1,String(req.params.id));if(!r)return res.status(404).json({error:'الإيصال غير موجود'});if(r.print_count>=3)return res.status(409).json({error:'تم الوصول للحد الأقصى: 3 مرات طباعة لهذا الإيصال'});db.prepare('UPDATE expense_receipts SET print_count=print_count+1 WHERE id=?').run(r.id);db.prepare('INSERT INTO audit_logs(user_id,action,entity,entity_id) VALUES(?,?,?,?)').run(req.user.id,'print_expense_receipt','expense_receipt',r.id);res.json({ok:true,print_count:r.print_count+1})});
// Explicitly authorized data deletion tools. Full booking deletion is blocked when financial entries exist.
app.get('/api/data-deletion/counts',auth,(req,res)=>{if(req.user.role!=='admin'&&!req.user.permissions.some(p=>['delete_inquiries','delete_bookings','delete_reports','delete_all_data'].includes(p)))return res.status(403).json({error:'ليس لديك صلاحية لإدارة حذف البيانات'});res.json({inquiries:db.prepare('SELECT COUNT(*) n FROM inquiries').get().n,bookings:db.prepare('SELECT COUNT(*) n FROM bookings').get().n,reports:0});});
app.post('/api/data-deletion/inquiries',auth,(req,res)=>{if(req.user.role!=='admin'&&!req.user.permissions.includes('delete_inquiries')&&!req.user.permissions.includes('delete_all_data'))return res.status(403).json({error:'ليس لديك صلاحية حذف الاستفسارات'});if(req.body?.confirm!=='DELETE_INQUIRIES')return res.status(400).json({error:'تأكيد الحذف غير صحيح'});try{const tx=db.transaction(()=>{db.prepare('DELETE FROM followups WHERE inquiry_id IN (SELECT id FROM inquiries)').run();db.prepare('DELETE FROM inquiry_events WHERE inquiry_id IN (SELECT id FROM inquiries)').run();const n=db.prepare('DELETE FROM inquiries').run().changes;db.prepare('INSERT INTO audit_logs(user_id,action,entity,details) VALUES(?,?,?,?)').run(req.user.id,'bulk_delete','inquiries',JSON.stringify({count:n}));return n});res.json({ok:true,deleted:tx()})}catch(e){res.status(400).json({error:'تعذر حذف الاستفسارات: '+e.message})}});
app.post('/api/data-deletion/bookings',auth,(req,res)=>{if(req.user.role!=='admin'&&!req.user.permissions.includes('delete_bookings')&&!req.user.permissions.includes('delete_all_data'))return res.status(403).json({error:'ليس لديك صلاحية حذف الحجوزات'});if(req.body?.confirm!=='DELETE_BOOKINGS')return res.status(400).json({error:'تأكيد الحذف غير صحيح'});const n=db.prepare('SELECT COUNT(*) n FROM bookings').get().n;const financial=db.prepare('SELECT COUNT(*) n FROM payments').get().n+db.prepare('SELECT COUNT(*) n FROM cash_journal WHERE booking_id IS NOT NULL').get().n+db.prepare('SELECT COUNT(*) n FROM contractor_payouts WHERE booking_id IS NOT NULL').get().n;if(financial)return res.status(409).json({error:'تم منع الحذف الجماعي لأن هناك سجلات تحصيل أو قيود مالية مرتبطة بالحجوزات. لا بد من معالجة هذه القيود بطريقة محاسبية آمنة أولًا.'});try{const tx=db.transaction(()=>{for(const t of ['booking_buffets','booking_addons','booking_operational_addons','booking_contractors','booking_status_history','booking_activity','booking_addon_sales','booking_adjustments','booking_change_requests','discount_requests','additional_discount_requests','inventory_alerts','inventory_movements']){try{db.prepare(`DELETE FROM ${t} WHERE booking_id IN (SELECT id FROM bookings)`).run()}catch(e){if(!/no such column|no such table/i.test(e.message))throw e}}const changes=db.prepare('DELETE FROM bookings').run().changes;db.prepare('INSERT INTO audit_logs(user_id,action,entity,details) VALUES(?,?,?,?)').run(req.user.id,'bulk_delete','bookings',JSON.stringify({count:changes}));return changes});res.json({ok:true,deleted:tx()})}catch(e){res.status(400).json({error:'تعذر حذف الحجوزات: '+e.message})}});
app.post('/api/data-deletion/reports',auth,(req,res)=>{if(req.user.role!=='admin'&&!req.user.permissions.includes('delete_reports')&&!req.user.permissions.includes('delete_all_data'))return res.status(403).json({error:'ليس لديك صلاحية حذف التقارير'});res.json({ok:true,deleted:0,message:'النظام الحالي ينشئ التقارير مباشرة من البيانات ولا يحتوي على جدول مستقل للتقارير المحفوظة؛ لم يتم حذف أي بيانات تشغيلية.'})});
app.get('/api/users',auth,permit('users'),(req,res)=>res.json(db.prepare('SELECT id,username,full_name,role,permissions,active,discount_normal,discount_special,created_at FROM users ORDER BY id').all().map(u=>({...u,permissions:JSON.parse(u.permissions)}))));
app.get('/api/official-holidays',auth,permit('users'),(req,res)=>res.json(db.prepare('SELECT * FROM official_holidays ORDER BY holiday_date').all()));
app.post('/api/official-holidays',auth,permit('users'),(req,res)=>{const {holiday_date,label='إجازة رسمية'}=req.body||{};if(!/^\d{4}-\d{2}-\d{2}$/.test(String(holiday_date||'')))return res.status(400).json({error:'اختر تاريخ الإجازة بصيغة صحيحة'});try{const x=db.prepare('INSERT INTO official_holidays(holiday_date,label,created_by) VALUES(?,?,?)').run(holiday_date,String(label||'إجازة رسمية').trim(),req.user.id);db.prepare('INSERT INTO audit_logs(user_id,action,entity,entity_id) VALUES(?,?,?,?)').run(req.user.id,'create_official_holiday','official_holiday',x.lastInsertRowid);res.json({ok:true})}catch(e){res.status(400).json({error:'التاريخ مسجل بالفعل أو غير صالح'})}});
app.delete('/api/official-holidays/:id',auth,permit('users'),(req,res)=>{db.prepare('DELETE FROM official_holidays WHERE id=?').run(req.params.id);res.json({ok:true})});
app.get('/api/discount-limit',auth,permit('bookings'),(req,res)=>res.json({limit:discountLimit(req.user.id,req.query.event_date),special:(()=>{const d=new Date(String(req.query.event_date||'')+'T12:00:00');return [4,5,6].includes(d.getDay())||!!db.prepare('SELECT 1 FROM official_holidays WHERE holiday_date=?').get(String(req.query.event_date))})()}));
app.post('/api/users',auth,permit('users'),(req,res)=>{const {username,password,full_name,role='employee',permissions=[],discount_normal=0,discount_special=0}=req.body||{};if(!username||!password||!full_name||String(password).length<10)return res.status(400).json({error:'أدخل الاسم واسم المستخدم وكلمة مرور 10 أحرف على الأقل'});if(!['employee','reception','cashier','accountant','manager','admin'].includes(role))return res.status(400).json({error:'تصنيف الموظف غير صحيح'});try{const selected=role==='admin'?PERMS:[...new Set([...normalizePermissions(permissions),...(role==='reception'?['bookings']:[])])];const normal=Math.max(0,Math.min(100,Number(discount_normal)||0)),special=Math.max(0,Math.min(100,Number(discount_special)||0));const info=db.prepare('INSERT INTO users(username,password_hash,full_name,role,permissions,discount_normal,discount_special) VALUES(?,?,?,?,?,?,?)').run(username,bcrypt.hashSync(password,12),full_name,role,JSON.stringify(selected),normal,special);res.json({id:info.lastInsertRowid,ok:true})}catch(e){res.status(400).json({error:'اسم المستخدم مستخدم بالفعل'})}});
app.put('/api/users/:id',auth,permit('users'),(req,res)=>{const {full_name,role,permissions,active,password,discount_normal,discount_special}=req.body||{};try{if(Number(req.params.id)===req.user.id&&active===0)return res.status(400).json({error:'لا يمكن تعطيل حسابك الحالي'});if(role!==undefined&&!['employee','reception','cashier','accountant','manager','admin'].includes(role))return res.status(400).json({error:'تصنيف الموظف غير صحيح'});const fields=[],vals=[];for(const [k,v] of [['full_name',full_name],['role',role],['active',active]])if(v!==undefined){fields.push(k+'=?');vals.push(v)}for(const [k,v] of [['discount_normal',discount_normal],['discount_special',discount_special]])if(v!==undefined){fields.push(k+'=?');vals.push(Math.max(0,Math.min(100,Number(v)||0)))}if(permissions!==undefined){fields.push('permissions=?');vals.push(JSON.stringify(role==='admin'?PERMS:[...new Set([...normalizePermissions(permissions),...(role==='reception'?['bookings']:[])])]))}if(password){if(password.length<10)return res.status(400).json({error:'كلمة المرور 10 أحرف على الأقل'});fields.push('password_hash=?');vals.push(bcrypt.hashSync(password,12))}if(fields.length)db.prepare(`UPDATE users SET ${fields.join(',')} WHERE id=?`).run(...vals,req.params.id);res.json({ok:true})}catch(e){res.status(400).json({error:e.message})}});
app.get('/api/customer-lookup',auth,permit('bookings'),(req,res)=>{const phone=String(req.query.phone||'').trim();if(phone.replace(/\D/g,'').length<7)return res.json(null);const digits=v=>String(v||'').replace(/\D/g,'');const norm=v=>{let x=digits(v);if(x.startsWith('0020'))x=x.slice(4);else if(x.startsWith('20')&&x.length>=12)x=x.slice(2);if(x.startsWith('0')&&x.length>=11)x=x.slice(1);return x};const target=norm(phone);const c=db.prepare('SELECT full_name customer_name,phone,phone2,id_number,nationality,bride_name,notes FROM customers ORDER BY id DESC').all().find(x=>norm(x.phone)===target);const i=db.prepare('SELECT customer_name,phone,bride_name,source,notes,event_location,event_type,event_date,event_period,guest_count,budget,requested_hall,status FROM inquiries ORDER BY id DESC').all().find(x=>norm(x.phone)===target);if(!c&&!i)return res.json(null);res.json({...i,...c,customer_name:c?.customer_name||i?.customer_name,phone:c?.phone||i?.phone,bride_name:c?.bride_name||i?.bride_name,source:i?.source||null,inquiry_status:i?.status||null,found_customer:!!c,found_inquiry:!!i})});
