app.post('/api/bookings/:id/files',auth,permit('bookings'),(req,res)=>{
 const bookingId=Number(req.params.id),d=req.body||{};
 if(!db.prepare('SELECT id FROM bookings WHERE id=?').get(bookingId))return res.status(404).json({error:'الحجز غير موجود'});
 if(!d.name||!d.data_url)return res.status(400).json({error:'اختر ملفًا أولًا'});
 const mime=String(d.mime_type||'').toLowerCase();
 if(!ALLOWED_BOOKING_MIME.has(mime))return res.status(400).json({error:'الملفات المسموح بها: PDF وJPG وPNG وWEBP فقط'});
 const match=String(d.data_url).match(/^data:([^;]+);base64,([A-Za-z0-9+/=]+)$/);
 if(!match||match[1].toLowerCase()!==mime)return res.status(400).json({error:'صيغة الملف غير صحيحة'});
 const buffer=Buffer.from(match[2],'base64');
 if(!buffer.length||buffer.length>10*1024*1024)return res.status(400).json({error:'الحد الأقصى لحجم الملف الواحد 10 ميجابايت'});
 const original=path.basename(String(d.name)).replace(/[\\x00-\\x1f]/g,'').slice(0,180)||'attachment';
 const ext=({ 'application/pdf':'.pdf','image/jpeg':'.jpg','image/png':'.png','image/webp':'.webp'})[mime];
 const stored=`${Date.now()}-${require('crypto').randomBytes(8).toString('hex')}${ext}`;
 const dir=path.join(BOOKING_FILES_DIR,String(bookingId));fs.mkdirSync(dir,{recursive:true});
 try{fs.writeFileSync(path.join(dir,stored),buffer,{flag:'wx'});const info=db.prepare('INSERT INTO booking_files(booking_id,original_name,stored_name,mime_type,file_size,uploaded_by) VALUES(?,?,?,?,?,?)').run(bookingId,original,stored,mime,buffer.length,req.user.id);db.prepare('INSERT INTO audit_logs(user_id,action,entity,entity_id) VALUES(?,?,?,?)').run(req.user.id,'upload','booking_file',info.lastInsertRowid);res.json({ok:true,id:info.lastInsertRowid,original_name:original,file_size:buffer.length});}catch(e){try{fs.unlinkSync(path.join(dir,stored))}catch{};res.status(500).json({error:'تعذر حفظ الملف'});}
});
