app.get('/api/reports/employee-sales',auth,(req,res)=>{ /* Every employee may see their own activity; cross-employee reports require reports permission or admin. */const from=String(req.query.from||'0001-01-01'),to=String(req.query.to||'9999-12-31'),requestedUserId=Number(req.query.user_id||0),userId=(req.user.role==='admin'||req.user.permissions.includes('reports'))?requestedUserId:req.user.id,bookingNo=String(req.query.booking_no||'').trim();let where="date(s.created_at)>=date(?) AND date(s.created_at)<=date(?)",params=[from,to];if(userId){where+=' AND s.user_id=?';params.push(userId)}if(bookingNo){where+=' AND b.booking_no LIKE ?';params.push('%'+bookingNo+'%')}const sales=db.prepare(`SELECT s.*,u.full_name employee,b.booking_no,b.event_date,c.full_name customer_name FROM booking_addon_sales s LEFT JOIN users u ON u.id=s.user_id JOIN bookings b ON b.id=s.booking_id LEFT JOIN customers c ON c.id=b.customer_id WHERE ${where} ORDER BY s.created_at DESC,s.id DESC`).all(...params);let activityWhere="date(a.created_at)>=date(?) AND date(a.created_at)<=date(?)";let ap=[from,to];if(userId){activityWhere+=' AND a.user_id=?';ap.push(userId)}if(bookingNo){activityWhere+=' AND b.booking_no LIKE ?';ap.push('%'+bookingNo+'%')}const activities=db.prepare(`SELECT a.*,u.full_name employee,b.booking_no,b.event_date,c.full_name customer_name FROM booking_activity a LEFT JOIN users u ON u.id=a.user_id JOIN bookings b ON b.id=a.booking_id LEFT JOIN customers c ON c.id=b.customer_id WHERE ${activityWhere} ORDER BY a.created_at DESC,a.id DESC`).all(...ap);const users=(req.user.role==='admin'||req.user.permissions.includes('reports'))?db.prepare("SELECT id,full_name,username FROM users WHERE active=1 ORDER BY full_name").all():db.prepare("SELECT id,full_name,username FROM users WHERE id=? AND active=1").all(req.user.id);const byEmployee=new Map();for(const u of users)byEmployee.set(u.id,{user_id:u.id,employee:u.full_name,username:u.username,bookings_created:0,bookings_touched:0,addons_added:0,sales_total:0,removed_value:0,net_changes:0,bookings:[]});for(const a of activities){if(!a.user_id)continue;const x=byEmployee.get(a.user_id)||{user_id:a.user_id,employee:a.employee||'غير معروف',username:'',bookings_created:0,bookings_touched:0,addons_added:0,sales_total:0,removed_value:0,net_changes:0,bookings:[]};x.bookings_touched++;if(a.action==='create_booking')x.bookings_created++;if(!x.bookings.includes(a.booking_no))x.bookings.push(a.booking_no);byEmployee.set(a.user_id,x)}for(const s of sales){if(!s.user_id)continue;const x=byEmployee.get(s.user_id)||{user_id:s.user_id,employee:s.employee||'غير معروف',username:'',bookings_created:0,bookings_touched:0,addons_added:0,sales_total:0,removed_value:0,net_changes:0,bookings:[]};if(s.change_type==='add'||(s.change_type==='quantity_change'&&Number(s.quantity_delta)>0)){x.addons_added+=Math.max(0,Number(s.quantity_delta));x.sales_total+=Math.max(0,Number(s.sales_delta))}if(s.change_type==='remove')x.removed_value+=Math.abs(Number(s.sales_delta));x.net_changes+=Number(s.sales_delta||0);if(!x.bookings.includes(s.booking_no))x.bookings.push(s.booking_no);byEmployee.set(s.user_id,x)}const employeeSummary=[...byEmployee.values()].filter(x=>x.bookings_touched||x.addons_added||x.bookings.length).map(x=>({...x,booking_count:x.bookings.length})).sort((a,b)=>b.sales_total-a.sales_total);const summary={sales_total:sales.reduce((n,x)=>n+Number(x.sales_delta||0),0),positive_sales:sales.filter(x=>x.change_type==='add'||(x.change_type==='quantity_change'&&Number(x.quantity_delta)>0)).reduce((n,x)=>n+Math.max(0,Number(x.sales_delta||0)),0),employees:new Set([...sales,...activities].map(x=>x.user_id).filter(Boolean)).size,bookings:new Set([...sales,...activities].map(x=>x.booking_id)).size};res.json({sales,activities,users,summary,employeeSummary,from,to,user_id:userId,booking_no:bookingNo})});
