Date.now().toString().slice(-8);const info=db.prepare(`INSERT INTO bookings(booking_no,customer_id,hall_id,hall_package_id,event_date,start_time,end_time,guest_count,nationality,deposit,deposit_refund_date,package_price,buffet_total,addons_total,discount,service_total,event_total,amount_due,status,notes,created_by,booking_stage,offer_id,offer_discount,buffet_discount,package_offer_discount,free_meals,extra_guest_total,event_type) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`).run(bookingNo,cust.lastInsertRowid,d.hall_id,d.hall_package_id,d.event_date,d.start_time,d.end_time,guests,d.nationality||'egyptian',deposit,d.event_date,Number(basePkg.price),buffetTotal,addonsTotal,discount,service,eventTotal,eventTotal+deposit,'pending_payment',d.notes||'',req.user.id,initialStage,offer?.id||null,offerDiscount,offerBuffetDiscount,offerPackageDiscount,offer?.offer_type==='package_free_meals'?Number(offer.free_meals||0):0,extraGuestTotal,String(d.event_type||'wedding'));for(const roomId of selectedRoomIds)db.prepare('INSERT INTO booking_bride_rooms(booking_id,room_id,start_at,end_at) VALUES(?,?,?,?)').run(info.lastInsertRowid,roomId,roomStart,roomEnd);for(const line of buffetLines){const b=db.prepare('SELECT * FROM buffet_packages WHERE id=?').get(line.id);if(b)db.prepare('INSERT INTO booking_buffets VALUES(?,?,?,?,?)').run(info.lastInsertRowid,line.id,line.guest_count,b.price_per_person,b.price_per_person*line.guest_count)}
