app.get('/api/availability',auth,(req,res)=>{const date=String(req.query.date||'');if(!/^\d{4}-\d{2}-\d{2}$/.test(date))return res.status(400).json({error:'تاريخ غير صحيح'});const halls=db.prepare('SELECT id,name FROM halls WHERE active=1 ORDER BY name').all();const bookings=db.prepare(`SELECT b.id,b.booking_no,b.hall_id,b.event_date,b.start_time,b.end_time,b.status,c.full_name customer_name FROM bookings b LEFT JOIN customers c ON c.id=b.customer_id WHERE b.event_date=? AND b.status!='cancelled' ORDER BY b.start_time`).all(date);res.json({date,halls:halls.map(h=>({...h,bookings:bookings.filter(b=>Number(b.hall_id)===Number(h.id))}))})});
