app.get('/api/notifications',auth,(req,res)=>{const rows=db.prepare(`SELECT a.id,a.action,a.entity,a.entity_id,a.created_at,a.details,u.full_name employee FROM audit_logs a LEFT JOIN users u ON u.id=a.user_id ORDER BY a.id DESC LIMIT 80`).all();const labels={delete:'تم حذف سجل',discount_request_created:'طلب خصم إضافي جديد',additional_discount_requested:'طلب خصم إضافي ثابت للمدير',additional_discount_approved:'تمت الموافقة على الخصم الإضافي',additional_discount_rejected:'تم رفض الخصم الإضافي',discount_approved:'تمت الموافقة على الخصم',discount_rejected:'تم رفض الخصم',create:'تم إنشاء سجل جديد',create_inquiry:'استفسار جديد',followup_result:'تم تسجيل نتيجة متابعة',create_booking:'تم إنشاء حجز',backup_export:'تم تنزيل نسخة احتياطية',backup_restore_uploaded:'تم رفع نسخة للاستعادة',receive_cash_booking_deposit:'تم تحصيل مقدم حجز',receive_cash_security_deposit:'تم تحصيل التأمين',receive_cash_total_due:'تم تحصيل إجمالي المستحق',reprint_collection_receipt:'إعادة طباعة إيصال تحصيل',cash_expense_receipt:'تسجيل مصروف / مشتريات',print_expense_receipt:'إعادة طباعة إيصال مصروف',edit_booking_details:'تعديل تفاصيل حجز',postpone_booking:'تأجيل حجز',cancel_booking:'إلغاء حجز'};const paymentNames={booking_deposit:'مقدم حجز',security_deposit:'تأمين',security_refund:'رد تأمين',total_due:'سداد إجمالي المستحق',...Object.fromEntries(Array.from({length:10},(_,i)=>['installment_'+(i+1),'دفعة '+(i+1)]))};const notificationPermission=r=>{if(req.user.role==='admin')return true;const a=String(r.action||'').toLowerCase(),e=String(r.entity||'').toLowerCase();if(a==='edit_booking_details'&&['cashier','accountant'].includes(String(req.user.role||'').toLowerCase()))return true;let key;if(a.includes('discount'))key='notify_discounts';else if(a.includes('followup')||a.includes('inquiry'))key='notify_followups';else if(a.includes('cash')||a.includes('payment')||a.includes('collection')||a.includes('backup')||e==='payment'||e==='cash_journal')key='notify_finance';else key='notify_system';return req.user.permissions.includes(key)};res.json(rows.filter(notificationPermission).map(r=>{let details='';try{if(r.details){const parsed=JSON.parse(r.details);if(parsed&&typeof parsed==='object'&&!Array.isArray(parsed)){const fieldNames={payment_type:'نوع الدفع',receipt_no:'رقم الإيصال',amount:'المبلغ',booking_id:'رقم الحجز الداخلي',booking_no:'رقم الحجز',security_deposit:'التأمين',security_refund:'رد التأمين',booking_deposit:'مقدم الحجز',reference:'المرجع',method:'طريقة الدفع',notes:'ملاحظات',reprint_number:'رقم إعادة الطباعة',discount_type:'نوع الخصم',percent:'النسبة',reason:'السبب',status:'الحالة',employee:'الموظف'};const valueNames={pending_payment:'بانتظار استكمال الدفع',confirmed:'مؤكد',cancelled:'ملغي',postponed:'مؤجل',security_deposit:'تأمين',security_refund:'رد تأمين',booking_deposit:'مقدم حجز',total_due:'سداد إجمالي المستحق',fixed:'مبلغ ثابت',percent:'نسبة مئوية'};details=Object.entries(parsed).map(([k,v])=>`${fieldNames[k]||k}: ${valueNames[String(v)]||String(v??'—')}`).join(' · ')}else details=String(r.details)}else details=''}catch{details=String(r.details||'')}if(r.entity==='payment'&&r.entity_id){const q=db.prepare(`SELECT p.receipt_no,p.amount,p.payment_type,p.method,p.reference,p.notes,p.paid_at,b.booking_no,c.full_name customer_name FROM payments p JOIN bookings b ON b.id=p.booking_id LEFT JOIN customers c ON c.id=b.customer_id WHERE p.id=?`).get(r.entity_id);if(q){r.title=r.action==='reprint_collection_receipt'?'إعادة طباعة إيصال تحصيل':(labels[r.action]||'عملية تحصيل جديدة');details=`الإيصال: ${q.receipt_no||'—'} · النوع: ${paymentNames[q.payment_type]||q.payment_type} · المبلغ: ${Number(q.amount||0).toLocaleString('en-US')} ج.م · الحجز: ${q.booking_no} · العميل: ${q.customer_name||'—'} · طريقة الدفع: ${q.method||'—'}${q.reference?' · المرجع: '+q.reference:''}${q.notes?' · ملاحظات: '+q.notes:''}`;if(r.action==='reprint_collection_receipt'&&details)details+=' · '+(r.details||'');}}else if(r.entity==='cash_journal'&&r.entity_id){const q=db.prepare(`SELECT j.entry_no,j.category,j.amount,j.method,j.description,j.payee,j.booking_id,b.booking_no,e.receipt_no FROM cash_journal j LEFT JOIN bookings b ON b.id=j.booking_id LEFT JOIN expense_receipts e ON e.journal_id=j.id WHERE j.id=?`).get(r.entity_id);if(q){r.title=labels[r.action]|| (r.action.includes('cash')?'عملية مالية جديدة':'حركة خزنة');details=`القيد: ${q.entry_no} · الإيصال: ${q.receipt_no||'—'} · البند: ${q.category} · المبلغ: ${Number(q.amount||0).toLocaleString('en-US')} ج.م · طريقة الدفع: ${q.method||'—'} · المستفيد: ${q.payee||'—'}${q.booking_no?' · الحجز: '+q.booking_no:''} · التفاصيل: ${q.description||'—'}`;}}else if(r.entity==='booking'&&r.entity_id){const q=db.prepare(`SELECT b.booking_no,b.event_date,b.guest_count,b.status,c.full_name customer_name,h.name hall_name FROM bookings b LEFT JOIN customers c ON c.id=b.customer_id LEFT JOIN halls h ON h.id=b.hall_id WHERE b.id=?`).get(r.entity_id);if(q){r.title=labels[r.action]||({edit_booking_details:'تم تعديل تفاصيل الحجز',postpone_booking:'تم تأجيل الحجز',cancel_booking:'تم إلغاء الحجز',create:'تم إنشاء الحجز'})[r.action]||'إجراء على حجز';let actionDetails='';if(r.action==='edit_booking_details'){const a=db.prepare("SELECT details FROM booking_activity WHERE booking_id=? AND action='edit_booking' ORDER BY id DESC LIMIT 1").get(r.entity_id);if(a){try{const x=JSON.parse(a.details||'{}'),o=x.old||{},n=x.new||{},changes=[];const compare=(key,label,format=v=>String(v??'—'))=>{if(JSON.stringify(o[key])!==JSON.stringify(n[key]))changes.push(`${label}: ${format(o[key])} ← ${format(n[key])}`)};compare('event_date','تاريخ المناسبة');compare('guest_count','عدد الأفراد');compare('hall_id','القاعة');compare('start_time','وقت البداية');compare('end_time','وقت النهاية');compare('discount','الخصم',v=>Number(v||0).toLocaleString('ar-EG')+' ج.م');compare('event_total','الإجمالي',v=>Number(v||0).toLocaleString('ar-EG')+' ج.م');if(Array.isArray(x.operational_addons)){const before=new Map(x.operational_addons.filter(v=>v.action==='before').map(v=>[String(v.name),Number(v.quantity||0)])),after=new Map(x.operational_addons.filter(v=>v.action==='after').map(v=>[String(v.name),Number(v.quantity||0)]));for(const name of new Set([...before.keys(),...after.keys()])){const b=before.get(name)||0,af=after.get(name)||0;if(b!==af)changes.push(b===0?`إضافة ${name} (الكمية ${af})`:af===0?`حذف ${name} (الكمية السابقة ${b})`:`${name}: الكمية من ${b} إلى ${af}`)}}actionDetails=changes.length?'التغييرات الفعلية: '+changes.join('؛ '):'تم تعديل الحجز، ولا توجد تفاصيل فروق قديمة محفوظة.'}catch{actionDetails=String(a.details||'')}}}else if(r.action==='postpone_booking'||r.action==='cancel_booking'){const h=db.prepare('SELECT old_event_date,new_event_date,reason,notes FROM booking_status_history WHERE booking_id=? ORDER BY id DESC LIMIT 1').get(r.entity_id);if(h)actionDetails=`التاريخ السابق: ${h.old_event_date||'—'} · التاريخ الجديد: ${h.new_event_date||'—'} · السبب: ${h.reason||'—'}${h.notes?' · ملاحظات: '+h.notes:''}`}details=`الحجز: ${q.booking_no} · العميل: ${q.customer_name||'—'} · القاعة: ${q.hall_name||'—'} · تاريخ المناسبة: ${q.event_date} · عدد الأفراد: ${q.guest_count} · الحالة: ${q.status}${actionDetails?' · '+actionDetails:''}`;}}else if(r.entity==='discount_request'&&r.entity_id){const q=db.prepare('SELECT r.status,r.percent,r.reason,r.review_note,b.booking_no,b.event_date,b.start_time,b.end_time,b.guest_count,c.full_name customer_name,c.phone,c.bride_name,h.name hall_name,p.name package_name,u.full_name requested_by_name FROM discount_requests r JOIN bookings b ON b.id=r.booking_id LEFT JOIN customers c ON c.id=b.customer_id JOIN halls h ON h.id=b.hall_id JOIN hall_packages p ON p.id=b.hall_package_id JOIN users u ON u.id=r.requested_by WHERE r.id=?').get(r.entity_id);if(q){details=`الحجز ${q.booking_no} · العميل ${q.customer_name||'—'} · الهاتف ${q.phone||'—'} · العروسة ${q.bride_name||'—'} · القاعة ${q.hall_name} · الباكدج ${q.package_name} · المناسبة ${q.event_date} ${q.start_time}-${q.end_time} · الأفراد ${q.guest_count} · الموظف ${q.requested_by_name} · الخصم ${q.percent}% · السبب ${q.reason}${q.review_note?' · ملاحظة المدير: '+q.review_note:''}`;r.title=q.status==='approved'?'تمت الموافقة على طلب الخصم':q.status==='rejected'?'تم رفض طلب الخصم':'طلب خصم إضافي يحتاج موافقة';}}else if(r.entity==='additional_discount_request'&&r.entity_id){const q=db.prepare('SELECT r.*,b.booking_no,b.event_date,b.start_time,b.end_time,b.guest_count,c.full_name customer_name,u.full_name requested_by_name,rv.full_name reviewed_by_name FROM additional_discount_requests r JOIN bookings b ON b.id=r.booking_id LEFT JOIN customers c ON c.id=b.customer_id JOIN users u ON u.id=r.requested_by LEFT JOIN users rv ON rv.id=r.reviewed_by WHERE r.id=?').get(r.entity_id);if(q){r.title=q.status==='approved'?'تمت الموافقة على الخصم الإضافي':q.status==='rejected'?'تم رفض الخصم الإضافي':'طلب خصم إضافي يحتاج موافقة المدير';details=`طلب رقم ${q.id} · الحجز ${q.booking_no} · العميل ${q.customer_name||'—'} · الموظف ${q.requested_by_name} · الخصم المطلوب ${Number(q.amount).toLocaleString('en-US')} ج.م · السبب: ${q.reason} · الحالة: ${q.status==='pending'?'معلق':q.status==='approved'?'موافق عليه':'مرفوض'}${q.reviewed_by_name?' · قرار المدير '+q.reviewed_by_name:''}${q.review_note?' · سبب القرار: '+q.review_note:''}`;if(req.user.role!=='admin'&&Number(q.requested_by)!==Number(req.user.id))return null;}}else if(r.entity==='booking_change_request'&&r.entity_id){const q=db.prepare(`SELECT r.*,b.booking_no,b.event_date,b.start_time,b.end_time,b.guest_count,c.full_name customer_name,c.phone,h.name hall_name,p.name package_name,u.full_name requested_by_name,rv.full_name reviewed_by_name FROM booking_change_requests r JOIN bookings b ON b.id=r.booking_id LEFT JOIN customers c ON c.id=b.customer_id JOIN halls h ON h.id=b.hall_id JOIN hall_packages p ON p.id=b.hall_package_id LEFT JOIN users u ON u.id=r.requested_by LEFT JOIN users rv ON rv.id=r.reviewed_by WHERE r.id=?`).get(r.entity_id);if(q){const typeAr=q.change_type==='change_date'?'تغيير أو تأجيل موعد':q.change_type==='cancel'?'إلغاء حجز':q.item_action==='add'?'إضافة صنف':'إلغاء صنف';const statusAr=q.status==='approved'?'تمت الموافقة على الطلب وتطبيقه تلقائيًا':q.status==='rejected'?'تم رفض الطلب':'الطلب في انتظار موافقة المدير';r.title=(q.status==='approved'?'تمت الموافقة على ':q.status==='rejected'?'تم رفض ':'طلب جديد: ')+typeAr;details=`${statusAr}. رقم الطلب: ${q.id}. رقم الحجز: ${q.booking_no}. العميل: ${q.customer_name||'غير مسجل'}. رقم الموبايل: ${q.phone||'غير مسجل'}. القاعة: ${q.hall_name}. الباكدج: ${q.package_name}. الموعد الحالي: ${q.old_event_date||q.event_date} ${q.start_time||''}-${q.end_time||''}. الموعد المطلوب: ${q.new_event_date||'لا يوجد تغيير تاريخ'} ${q.new_start_time||''}-${q.new_end_time||''}. نوع العملية: ${typeAr}. تفاصيل الصنف: ${q.item_details||'لا يوجد'}. سبب العميل: ${q.reason||'غير مسجل'}. المبلغ المعتمد: ${Number(q.amount||0).toLocaleString('ar-EG')} ج.م. الموظف: ${q.requested_by_name||'غير معروف'}. المدير: ${q.reviewed_by_name||'لم يراجع بعد'}. ملاحظة المدير: ${q.review_note||'لا توجد'}`;}}else if(r.entity==='inquiry'&&r.entity_id){const q=db.prepare('SELECT customer_name,phone,bride_name,status,notes FROM inquiries WHERE id=?').get(r.entity_id);if(q){details=`العميل: ${q.customer_name} · الهاتف: ${q.phone} · الحالة: ${q.status}${q.bride_name?' · العروسة: '+q.bride_name:''}${q.notes?' · التفاصيل: '+q.notes:''}`;r.title=labels[r.action]||'تحديث استفسار / متابعة';}}if(!details)details=r.entity+(r.entity_id?' #'+r.entity_id:'');return {...r,title:r.title||labels[r.action]||String(r.action||'عملية جديدة').replaceAll('_',' '),details}}))});

// Request an additional fixed-amount discount; only a system admin can approve/reject it.
app.post('/api/bookings/:id/additional-discount-requests',auth,(req,res)=>{if(!req.user.permissions.includes('bookings')&&!req.user.permissions.includes('finance')&&req.user.role!=='admin')return res.status(403).json({error:'ليس لديك صلاحية لطلب خصم على الحجز'});const booking=db.prepare(`SELECT b.*,c.full_name customer_name FROM bookings b LEFT JOIN customers c ON c.id=b.customer_id WHERE b.id=?`).get(req.params.id);if(!booking)return res.status(404).json({error:'الحجز غير موجود'});if(booking.status==='cancelled')return res.status(400).json({error:'لا يمكن طلب خصم لحجز ملغي'});const discountType=req.body?.discount_type==='percent'?'percent':'fixed',percent=Number(req.body?.percent||0),requested=Number(req.body?.amount||0),reason=String(req.body?.reason||'').trim();const remaining=Math.max(0,Number(booking.event_total)+Number(booking.deposit)-Number(booking.special_discount||0));let amount=discountType==='percent'?Math.round(remaining*percent)/100:Math.round(requested*100)/100;if(discountType==='percent'&&(!Number.isFinite(percent)||percent<=0||percent>100))return res.status(400).json({error:'أدخل نسبة خصم أكبر من صفر ولا تتجاوز 100%'});if(!Number.isFinite(amount)||amount<=0||amount>remaining+0.001)return res.status(400).json({error:`اكتب خصمًا صحيحًا لا يتجاوز الإجمالي المتبقي ${remaining.toFixed(2)} جنيه`});if(reason.length<5)return res.status(400).json({error:'اكتب سبب الخصم بالتفصيل (5 أحرف على الأقل)'});if(db.prepare("SELECT 1 FROM additional_discount_requests WHERE booking_id=? AND status='pending'").get(booking.id))return res.status(409).json({error:'يوجد طلب خصم إضافي معلق لهذا الحجز بالفعل'});const tx=db.transaction(()=>{const x=db.prepare('INSERT INTO additional_discount_requests(booking_id,requested_by,amount,reason,discount_type,percent) VALUES(?,?,?,?,?,?)').run(booking.id,req.user.id,amount,reason,discountType,discountType==='percent'?percent:0);const serial='NS-AD-'+String(x.lastInsertRowid).padStart(6,'0');db.prepare('UPDATE additional_discount_requests SET serial_code=? WHERE id=?').run(serial,x.lastInsertRowid);db.prepare("UPDATE bookings SET booking_stage='awaiting_manager' WHERE id=?").run(booking.id);db.prepare('INSERT INTO audit_logs(user_id,action,entity,entity_id,details) VALUES(?,?,?,?,?)').run(req.user.id,'additional_discount_requested','additional_discount_request',x.lastInsertRowid,JSON.stringify({serial_code:serial,booking_no:booking.booking_no,amount,discount_type:discountType,percent,reason,customer_name:booking.customer_name}));db.prepare('INSERT INTO booking_activity(booking_id,user_id,action,details) VALUES(?,?,?,?)').run(booking.id,req.user.id,'additional_discount_requested',JSON.stringify({request_id:x.lastInsertRowid,serial_code:serial,amount,discount_type:discountType,percent,reason}));return {id:x.lastInsertRowid,serial_code:serial,amount}});const created=tx();res.json({ok:true,...created,message:'تم إرسال طلب الخصم الإضافي للمدير فقط'})});
app.get('/api/additional-discount-requests',auth,(req,res)=>{if(req.user.role!=='admin'&&!req.user.permissions.includes('discounts'))return res.status(403).json({error:'طلبات الخصم الإضافي متاحة للمدير فقط'});const rows=db.prepare(`SELECT r.*,b.booking_no,b.event_date,b.start_time,b.end_time,b.guest_count,b.event_total,b.deposit,b.special_discount,b.package_price,b.buffet_total,b.addons_total,c.full_name customer_name,c.phone,h.name hall_name,p.name package_name,u.username requested_by_username,u.full_name requested_by_name FROM additional_discount_requests r JOIN bookings b ON b.id=r.booking_id LEFT JOIN customers c ON c.id=b.customer_id JOIN halls h ON h.id=b.hall_id JOIN hall_packages p ON p.id=b.hall_package_id JOIN users u ON u.id=r.requested_by ORDER BY CASE r.status WHEN 'pending' THEN 0 ELSE 1 END,r.created_at DESC`).all();res.json(rows)});
app.post('/api/additional-discount-requests/:id/decision',auth,(req,res)=>{if(req.user.role!=='admin'&&!req.user.permissions.includes('discounts'))return res.status(403).json({error:'اعتماد الخصم الإضافي متاح للمدير المخوّل فقط'});const {decision,review_note=''}=req.body||{};if(!['approved','rejected'].includes(decision))return res.status(400).json({error:'قرار غير صحيح'});if(String(review_note).trim().length<3)return res.status(400).json({error:'اكتب سبب الموافقة أو الرفض ليظهر للموظف والكاشير والمحاسب'});const row=db.prepare("SELECT r.*,b.booking_no,b.event_total,b.deposit,b.special_discount FROM additional_discount_requests r JOIN bookings b ON b.id=r.booking_id WHERE r.id=? AND r.status='pending'").get(req.params.id);if(!row)return res.status(404).json({error:'طلب الخصم غير موجود أو تم اتخاذ قرار فيه'});const tx=db.transaction(()=>{if(decision==='approved'){const total=Number(row.event_total)+Number(row.deposit)-Number(row.special_discount||0);if(Number(row.amount)>total+0.001)throw new Error('الخصم المطلوب أكبر من الإجمالي الحالي للحجز');db.prepare('UPDATE bookings SET special_discount=COALESCE(special_discount,0)+? WHERE id=?').run(row.amount,row.booking_id)}db.prepare('UPDATE additional_discount_requests SET status=?,reviewed_by=?,review_note=?,reviewed_at=CURRENT_TIMESTAMP WHERE id=?').run(decision,req.user.id,String(review_note).trim(),row.id);const pending=db.prepare("SELECT (SELECT COUNT(*) FROM discount_requests WHERE booking_id=? AND status='pending')+(SELECT COUNT(*) FROM additional_discount_requests WHERE booking_id=? AND status='pending') n").get(row.booking_id,row.booking_id).n;if(!pending)db.prepare('UPDATE bookings SET booking_stage=? WHERE id=?').run(decision==='approved'?'confirmed':'preliminary',row.booking_id);const action=decision==='approved'?'additional_discount_approved':'additional_discount_rejected';db.prepare('INSERT INTO audit_logs(user_id,action,entity,entity_id,details) VALUES(?,?,?,?,?)').run(req.user.id,action,'additional_discount_request',row.id,JSON.stringify({booking_no:row.booking_no,amount:row.amount,review_note:String(review_note).trim(),status:decision}));db.prepare('INSERT INTO booking_activity(booking_id,user_id,action,details) VALUES(?,?,?,?)').run(row.booking_id,req.user.id,action,JSON.stringify({request_id:row.id,amount:row.amount,reason:row.reason,review_note:String(review_note).trim(),status:decision}));});try{tx();res.json({ok:true,status:decision})}catch(e){res.status(400).json({error:e.message})}});

