 const rows=db.prepare(`SELECT b.id,b.booking_no,b.event_date,b.start_time,b.end_time,b.guest_count,b.event_total,b.deposit,b.special_discount,COALESCE((SELECT r.id FROM additional_discount_requests r WHERE r.booking_id=b.id AND r.status='approved' ORDER BY r.id DESC LIMIT 1),0) special_discount_request_id,b.status,c.full_name customer_name,c.phone,h.name hall_name,p.name package_name,COALESCE((SELECT SUM(amount) FROM payments x WHERE x.booking_id=b.id AND x.payment_type!='security_refund'),0) paid, (b.event_total+b.deposit-COALESCE(b.special_discount,0)) final_total, COALESCE((SELECT SUM(amount) FROM payments x WHERE x.booking_id=b.id AND x.payment_type='security_deposit'),0) security_paid FROM bookings b LEFT JOIN customers c ON c.id=b.customer_id JOIN halls h ON h.id=b.hall_id JOIN hall_packages p ON p.id=b.hall_package_id WHERE b.status!='cancelled' ORDER BY CASE WHEN b.status='pending_payment' THEN 0 ELSE 1 END,b.created_at DESC`).all();res.json(rows);
