app.get('/api/collection/receipt-by-no/:receiptNo',auth,permit('cashbox'),(req,res)=>{const receipt=String(req.params.receiptNo||'').trim();const row=db.prepare(`SELECT p.id payment_id,p.booking_id,p.receipt_no,p.payment_type,p.amount,p.paid_at,p.notes,b.booking_no,b.event_date,c.full_name customer_name,c.phone,COALESCE((SELECT SUM(x.amount) FROM payments x WHERE x.booking_id=b.id AND x.payment_type='security_deposit'),0) security_held,COALESCE((SELECT SUM(x.amount) FROM payments x WHERE x.booking_id=b.id AND x.payment_type='security_refund'),0) security_refunded FROM payments p JOIN bookings b ON b.id=p.booking_id LEFT JOIN customers c ON c.id=b.customer_id WHERE p.receipt_no=?`).get(receipt);if(!row)return res.status(404).json({error:'لم يتم العثور على إيصال بهذا الرقم.'});res.json(row)});
