// Inventory module: receipts, adjustments, movement ledger, and low-stock alerts.
app.get('/api/inventory',auth,permit('inventory'),(req,res)=>{const items=db.prepare(`SELECT i.*,b.name buffet_item_name,a.name addon_name,COALESCE((SELECT SUM(shortage_qty) FROM inventory_alerts al WHERE al.item_id=i.id AND al.status='open'),0) shortage_open FROM inventory_items i LEFT JOIN buffet_items b ON b.id=i.buffet_item_id LEFT JOIN addons a ON a.id=i.addon_id ORDER BY i.name`).all();const buffetItems=db.prepare('SELECT id,name,active FROM buffet_items ORDER BY name').all();const buffetAddons=db.prepare('SELECT id,name,active FROM addons ORDER BY name').all();const alerts=db.prepare(`SELECT a.*,i.name item_name,i.unit,b.booking_no FROM inventory_alerts a JOIN inventory_items i ON i.id=a.item_id LEFT JOIN bookings b ON b.id=a.booking_id WHERE a.status='open' ORDER BY a.id DESC LIMIT 100`).all();const movements=db.prepare(`SELECT m.*,i.name item_name,i.unit,u.full_name employee,b.booking_no FROM inventory_movements m JOIN inventory_items i ON i.id=m.item_id LEFT JOIN users u ON u.id=m.created_by LEFT JOIN bookings b ON b.id=m.booking_id ORDER BY m.id DESC LIMIT 100`).all();res.json({items,buffetItems,buffetAddons,alerts,movements})});
app.post('/api/inventory/items',auth,permit('inventory'),(req,res)=>{try{const d=req.body||{};if(!String(d.name||'').trim())return res.status(400).json({error:'اكتب اسم الصنف'});const sourceType=d.source_type==='addon'?'addon':'menu';const linkId=Number(d.link_id||d.buffet_item_id||0);if(linkId&&sourceType==='menu'&&!db.prepare('SELECT id FROM buffet_items WHERE id=?').get(linkId))return res.status(400).json({error:'صنف المنيو المختار غير موجود'});if(linkId&&sourceType==='addon'&&!db.prepare('SELECT id FROM addons WHERE id=?').get(linkId))return res.status(400).json({error:'إضافة البوفيه المختارة غير موجودة'});const qty=Number(d.stock),min=Number(d.min_stock);if(!Number.isFinite(qty)||qty<0||!Number.isFinite(min)||min<0)return res.status(400).json({error:'الرصيد وحد التنبيه يجب أن يكونا أرقامًا صحيحة غير سالبة'});const x=db.prepare('INSERT INTO inventory_items(name,unit,stock,min_stock,buffet_item_id,addon_id,source_type,units_per_buffet_unit) VALUES(?,?,?,?,?,?,?,?)').run(String(d.name).trim(),String(d.unit||'قطعة').trim(),qty,min,linkId&&sourceType==='menu'?linkId:null,linkId&&sourceType==='addon'?linkId:null,sourceType,Math.max(0.0001,Number(d.units_per_buffet_unit)||1));if(qty)db.prepare("INSERT INTO inventory_movements(item_id,movement_type,quantity,balance_after,notes,created_by) VALUES(?,'in',?,?,?,?)").run(x.lastInsertRowid,qty,qty,'رصيد افتتاحي',req.user.id);db.prepare('INSERT INTO audit_logs(user_id,action,entity,entity_id) VALUES(?,?,?,?)').run(req.user.id,'inventory_item_created','inventory_item',x.lastInsertRowid);res.json({ok:true,id:x.lastInsertRowid})}catch(e){res.status(400).json({error:e.message.includes('UNIQUE')?'اسم الصنف مسجل بالفعل':e.message})}});
app.delete('/api/inventory/items/:id',auth,(req,res,next)=>{if(req.user.role==='admin'||req.user.permissions.includes('delete_inventory')||req.user.permissions.includes('delete_all_data'))return next();return res.status(403).json({error:'ليس لديك صلاحية مسح أصناف المخزن'});},(req,res)=>{try{const item=db.prepare('SELECT id,name FROM inventory_items WHERE id=?').get(req.params.id);if(!item)return res.status(404).json({error:'الصنف غير موجود'});const linked=db.prepare('SELECT COUNT(*) n FROM inventory_movements WHERE item_id=?').get(item.id).n+db.prepare('SELECT COUNT(*) n FROM inventory_alerts WHERE item_id=?').get(item.id).n;if(linked)return res.status(409).json({error:'لا يمكن مسح الصنف لأن له حركات أو تنبيهات مسجلة. للحفاظ على سجل المخزن، عطّله بدلًا من مسح تاريخه.'});db.prepare('DELETE FROM inventory_items WHERE id=?').run(item.id);db.prepare('INSERT INTO audit_logs(user_id,action,entity,entity_id,details) VALUES(?,?,?,?,?)').run(req.user.id,'delete','inventory_item',item.id,JSON.stringify({name:item.name}));res.json({ok:true})}catch(e){res.status(400).json({error:'تعذر مسح الصنف؛ قد يكون مرتبطًا ببيانات أخرى.'})}});
app.post('/api/inventory/items/:id/movement',auth,permit('inventory'),(req,res)=>{try{const d=req.body||{},qty=Number(d.quantity),type=d.type;if(!['in','out','adjustment'].includes(type)||!Number.isFinite(qty)||qty<=0)return res.status(400).json({error:'حدد نوع الحركة وكمية صحيحة أكبر من صفر'});const tx=db.transaction(()=>{const item=db.prepare('SELECT * FROM inventory_items WHERE id=? AND active=1').get(req.params.id);if(!item)throw Error('الصنف غير موجود');let balance=type==='in'?item.stock+qty:type==='out'?item.stock-qty:qty;if(balance<0)throw Error('الرصيد غير كافٍ. المتاح '+item.stock+' '+item.unit);db.prepare('UPDATE inventory_items SET stock=? WHERE id=?').run(balance,item.id);db.prepare('INSERT INTO inventory_movements(item_id,movement_type,quantity,balance_after,notes,created_by) VALUES(?,?,?,?,?,?)').run(item.id,type,qty,balance,String(d.notes||''),req.user.id);db.prepare('INSERT INTO audit_logs(user_id,action,entity,entity_id) VALUES(?,?,?,?)').run(req.user.id,'inventory_'+type,'inventory_item',item.id);return {ok:true,balance}});res.json(tx())}catch(e){res.status(400).json({error:e.message})}});
app.post('/api/inventory/alerts/:id/resolve',auth,permit('inventory'),(req,res)=>{db.prepare("UPDATE inventory_alerts SET status='resolved' WHERE id=?").run(req.params.id);res.json({ok:true})});

// Work orders API: order documents never expose financial values to operational teams.
app.get('/api/work-orders',auth,permit('work_orders'),(req,res)=>{try{for(const cb of db.prepare("SELECT id,cancel_reason FROM bookings WHERE status='cancelled'").all())cancelBookingWorkOrders(cb.id,req.user.id,cb.cancel_reason||'تم إلغاء الحجز');const from=String(req.query.from||'0001-01-01'),to=String(req.query.to||'9999-12-31'),type=String(req.query.type||''),status=String(req.query.status||''),q=String(req.query.q||'').trim();const bookingPhone=String(req.query.booking_phone||'').trim();let sql=`SELECT wo.*,b.booking_no,b.event_date,b.start_time,b.end_time,b.guest_count,b.status booking_status,b.booking_stage,c.full_name customer_name,h.name hall_name,p.name package_name,co.full_name contractor_name,co.job_title contractor_job,c.phone customer_phone FROM work_orders wo JOIN bookings b ON b.id=wo.booking_id LEFT JOIN customers c ON c.id=b.customer_id JOIN halls h ON h.id=b.hall_id JOIN hall_packages p ON p.id=b.hall_package_id LEFT JOIN contractors co ON co.id=wo.contractor_id WHERE date(b.event_date)>=date(?) AND date(b.event_date)<=date(?)`;const params=[from,to];if(type){sql+=' AND wo.order_type=?';params.push(type)}if(status){sql+=' AND wo.status=?';params.push(status)}if(q){sql+=' AND (wo.serial_no LIKE ? OR b.booking_no LIKE ? OR c.full_name LIKE ? OR c.phone LIKE ? OR h.name LIKE ? OR co.full_name LIKE ?)';params.push(...Array(6).fill('%'+q+'%'))}sql+=' ORDER BY b.event_date, b.start_time, wo.id';const rows=db.prepare(sql).all(...params).map(o=>({...o,lines:db.prepare('SELECT * FROM work_order_lines WHERE work_order_id=? ORDER BY id').all(o.id)}));const bookingSql=`SELECT b.id,b.booking_no,b.event_date,b.start_time,b.end_time,b.guest_count,b.status,b.booking_stage,c.full_name customer_name,c.phone customer_phone,h.name hall_name,p.name package_name FROM bookings b LEFT JOIN customers c ON c.id=b.customer_id JOIN halls h ON h.id=b.hall_id JOIN hall_packages p ON p.id=b.hall_package_id WHERE b.status!='cancelled' ${bookingPhone ? "AND REPLACE(REPLACE(REPLACE(REPLACE(COALESCE(c.phone,''),' ',''),'-',''),'+',''),'(','') LIKE ?" : ''} ORDER BY b.event_date DESC LIMIT 500`;const bookings=bookingPhone?db.prepare(bookingSql).all('%'+bookingPhone.replace(/[\s()+-]/g,'')+'%'):db.prepare(bookingSql).all();res.json({rows,bookings,contractors:db.prepare('SELECT c.id,c.full_name,c.job_title,c.hall_id,h.name hall_name,c.cost_per_booking FROM contractors c JOIN halls h ON h.id=c.hall_id WHERE c.active=1 ORDER BY c.job_title,c.full_name').all()})}catch(e){res.status(500).json({error:'تعذر تحميل أوامر الشغل: '+e.message})}});
app.post('/api/work-orders/generate/:bookingId',auth,permit('work_orders'),(req,res)=>{try{const b=db.prepare('SELECT * FROM bookings WHERE id=?').get(Number(req.params.bookingId));if(!b)return res.status(404).json({error:'الحجز غير موجود'});if(b.status==='cancelled')return res.status(400).json({error:'لا يمكن إصدار أوامر شغل لحجز ملغي'});if(b.booking_stage!=='confirmed')return res.status(400).json({error:'لازم يكون الحجز مؤكدًا قبل إصدار أوامر الشغل'});const result=generateBookingWorkOrders(b.id,req.user.id);db.prepare('INSERT INTO audit_logs(user_id,action,entity,entity_id,details) VALUES(?,?,?,?,?)').run(req.user.id,'work_orders_generated','booking',b.id,JSON.stringify({created:result.created}));res.json({ok:true,...result,message:result.created?'تم إصدار/تحديث أوامر الشغل':'تمت مراجعة أوامر الشغل'})}catch(e){res.status(400).json({error:e.message})}});
app.post('/api/work-orders/assign-contractor/:bookingId',auth,permit('work_orders'),(req,res)=>{try{const bookingId=Number(req.params.bookingId),d=req.body||{},contractorId=Number(d.contractor_id),cost=Number(d.cost_amount),details=String(d.service_details||'').trim();const b=db.prepare('SELECT * FROM bookings WHERE id=?').get(bookingId),c=db.prepare('SELECT * FROM contractors WHERE id=? AND active=1').get(contractorId);if(!b||b.status==='cancelled')return res.status(404).json({error:'الحجز غير موجود أو ملغي'});if(!c)return res.status(400).json({error:'اختار متعهدًا فعالًا'});if(!Number.isFinite(cost)||cost<0)return res.status(400).json({error:'التكلفة يجب أن تكون صفرًا أو أكثر'});if(!details)return res.status(400).json({error:'اكتب تفاصيل الخدمة المطلوبة للمتعهد'});const tx=db.transaction(()=>{db.prepare('UPDATE booking_work_contractors SET active=0 WHERE booking_id=? AND contractor_id=? AND active=1').run(bookingId,contractorId);db.prepare('INSERT INTO booking_work_contractors(booking_id,contractor_id,cost_amount,service_details,created_by) VALUES(?,?,?,?,?)').run(bookingId,contractorId,cost,details,req.user.id);db.prepare('INSERT INTO audit_logs(user_id,action,entity,entity_id,details) VALUES(?,?,?,?,?)').run(req.user.id,'work_contractor_assigned','booking',bookingId,JSON.stringify({contractor_id:contractorId,cost_amount:cost,service_details:details}));});tx();const result=generateBookingWorkOrders(bookingId,req.user.id);res.json({ok:true,...result,message:'تم إسناد المتعهد وتحديث أوامر الشغل'})}catch(e){res.status(400).json({error:e.message})}});
app.put('/api/work-orders/:id/status',auth,permit('work_orders'),(req,res)=>{const id=Number(req.params.id),status=String(req.body?.status||'');if(!['new','printed','delivered','in_progress','completed','cancelled'].includes(status))return res.status(400).json({error:'حالة أمر الشغل غير صحيحة'});const wo=db.prepare('SELECT * FROM work_orders WHERE id=?').get(id);if(!wo)return res.status(404).json({error:'أمر الشغل غير موجود'});if(wo.status==='cancelled'&&status!=='cancelled')return res.status(400).json({error:'أمر الشغل الملغي لا يعاد تفعيله؛ أنشئ إصدارًا جديدًا بعد مراجعة الحجز'});db.prepare('UPDATE work_orders SET status=?,updated_at=CURRENT_TIMESTAMP WHERE id=?').run(status,id);recordWorkOrderHistory(id,wo.version,'status_changed',{old_status:wo.status,new_status:status},req.user.id);db.prepare('INSERT INTO audit_logs(user_id,action,entity,entity_id,details) VALUES(?,?,?,?,?)').run(req.user.id,'work_order_status_changed','work_order',id,JSON.stringify({old_status:wo.status,new_status:status}));res.json({ok:true,status})});
app.get('/api/work-orders/:id/history',auth,permit('work_orders'),(req,res)=>{const rows=db.prepare('SELECT wh.*,u.full_name employee FROM work_order_history wh LEFT JOIN users u ON u.id=wh.user_id WHERE wh.work_order_id=? ORDER BY wh.id DESC').all(req.params.id);res.json(rows)});

